-- S02M043T（ショップ商品マスタ）099903／099904 の追加
-- 軽減税率変更対応_LI 20261127
-- ユーザー指示の「S02T043T」は、リポジトリのテーブル定義・生成設定で実在する S02M043T
-- （ショップ商品マスタ）として作成した。対象は 099902 を持つ AP基本コード×ショップコード。
-- 099903 は同じ AP基本コード×ショップコードの 099901 の行を、099904 は 099902 の行を複写する。
-- 税区分は複写元のまま（099903＝'1'、099904＝'4'。族で固定する登録原則どおり）。
-- 販売開始日・販売終了日を含む他項目も複写元のまま。既存行は変更しない。
-- 実行順序：05_S02M007T の後（S02M007T に 099903／099904 がある AP基本コードのみ追加する）。

-- START

SELECT 'S02M043T-ST' AS WORKNAME, TO_CHAR(SYSTIMESTAMP, 'YYYY/MM/DD HH24:MI:SS') AS DTM FROM dual;

-- 確認前
SELECT '確認前' AS WORKNAME, 'S02M043T' AS TABLENM, Count(*) AS CNT FROM S02M043T WHERE SHNCD IN ('099901', '099902', '099903', '099904');

PAUSE Adjust paper and press RETURN to continue.

-- 099903（一般・直前税率分）：099901 の行を複写
INSERT INTO S02M043T (APKIHONCD, SHOPCD, SHNCD, HANBAISTRTDD, HANBAISHRYDD, GAIBURENKEISHNCD, HONBUHANBAIKANRISHNCD, MGNTRGTKBN, SHNKBN, MOBILERIYOUMU, TAXSETTEIKBN, TAXKBN, SIIRETRTSKITANI, SIIREIRISU, SIIRETANI, SIIREUNT, HACCHUROTTOKAZU, URITRTSKITANI, URIIRISU, URITANI, OPNPRICEKIRIKAEDD, GENZOPNPRICE, SHINOPNPRICE, GENZOPNMOCHIKAERIPRICE, SHINOPNMOCHIKAERIPRICE, HANSOKUKBN, HANSOKUSTRTDD, HANSOKUSHRYDD, HANSOKUNM, HANSOKUDLVRYPRICE, HANSOKUMOCHIKAERIPRICE, HANSOKUYUSENKBN, ZAIKOKANRITRGTFLG, GENKAKEISANKBN, HYOJUNGENKA, ZAIKOUNT, SIIRETANIHENKANKBN, ZAIKOARAMUSURYO, BIKO, KAIINSAITORENKEIKBN, YUKOKBN, TOSHAAPKIHONCD, TOSHASHOPCD, TOSHACD, INPTSYSTMYMD, INPTSYSTMJIKAN, INPTUNYOYMD, INPTIPADRSE, INPTPGMID, KOSHAAPKIHONCD, KOSHASHOPCD, KOSHACD, KSHNSYSTMYMD, KSHNSYSTMJIKAN, KSHNUNYOYMD, KSHNIPADRSE, KSHNPGMID)
SELECT APKIHONCD, SHOPCD, '099903', HANBAISTRTDD, HANBAISHRYDD, GAIBURENKEISHNCD, HONBUHANBAIKANRISHNCD, MGNTRGTKBN, SHNKBN, MOBILERIYOUMU, TAXSETTEIKBN, TAXKBN, SIIRETRTSKITANI, SIIREIRISU, SIIRETANI, SIIREUNT, HACCHUROTTOKAZU, URITRTSKITANI, URIIRISU, URITANI, OPNPRICEKIRIKAEDD, GENZOPNPRICE, SHINOPNPRICE, GENZOPNMOCHIKAERIPRICE, SHINOPNMOCHIKAERIPRICE, HANSOKUKBN, HANSOKUSTRTDD, HANSOKUSHRYDD, HANSOKUNM, HANSOKUDLVRYPRICE, HANSOKUMOCHIKAERIPRICE, HANSOKUYUSENKBN, ZAIKOKANRITRGTFLG, GENKAKEISANKBN, HYOJUNGENKA, ZAIKOUNT, SIIRETANIHENKANKBN, ZAIKOARAMUSURYO, BIKO, KAIINSAITORENKEIKBN, YUKOKBN, '001', '000', 'SYSTEM', TO_CHAR(SYSDATE, 'YYYYMMDD'), TO_CHAR(SYSTIMESTAMP, 'HH24MISS'), TO_CHAR(SYSDATE, 'YYYYMMDD'), '127.0.0.1', 'MENTE', '001', '000', 'SYSTEM', TO_CHAR(SYSDATE, 'YYYYMMDD'), TO_CHAR(SYSTIMESTAMP, 'HH24MISS'), TO_CHAR(SYSDATE, 'YYYYMMDD'), '127.0.0.1', 'MENTE'
FROM S02M043T S
WHERE S.SHNCD = '099901'
  AND EXISTS (SELECT 1 FROM S02M043T T WHERE T.APKIHONCD = S.APKIHONCD AND T.SHOPCD = S.SHOPCD AND T.SHNCD = '099902')
  AND EXISTS (SELECT 1 FROM S02M007T M WHERE M.APKIHONCD = S.APKIHONCD AND M.SHNCD = '099903');

-- 099904（軽減・直前税率分）：099902 の行を複写
INSERT INTO S02M043T (APKIHONCD, SHOPCD, SHNCD, HANBAISTRTDD, HANBAISHRYDD, GAIBURENKEISHNCD, HONBUHANBAIKANRISHNCD, MGNTRGTKBN, SHNKBN, MOBILERIYOUMU, TAXSETTEIKBN, TAXKBN, SIIRETRTSKITANI, SIIREIRISU, SIIRETANI, SIIREUNT, HACCHUROTTOKAZU, URITRTSKITANI, URIIRISU, URITANI, OPNPRICEKIRIKAEDD, GENZOPNPRICE, SHINOPNPRICE, GENZOPNMOCHIKAERIPRICE, SHINOPNMOCHIKAERIPRICE, HANSOKUKBN, HANSOKUSTRTDD, HANSOKUSHRYDD, HANSOKUNM, HANSOKUDLVRYPRICE, HANSOKUMOCHIKAERIPRICE, HANSOKUYUSENKBN, ZAIKOKANRITRGTFLG, GENKAKEISANKBN, HYOJUNGENKA, ZAIKOUNT, SIIRETANIHENKANKBN, ZAIKOARAMUSURYO, BIKO, KAIINSAITORENKEIKBN, YUKOKBN, TOSHAAPKIHONCD, TOSHASHOPCD, TOSHACD, INPTSYSTMYMD, INPTSYSTMJIKAN, INPTUNYOYMD, INPTIPADRSE, INPTPGMID, KOSHAAPKIHONCD, KOSHASHOPCD, KOSHACD, KSHNSYSTMYMD, KSHNSYSTMJIKAN, KSHNUNYOYMD, KSHNIPADRSE, KSHNPGMID)
SELECT APKIHONCD, SHOPCD, '099904', HANBAISTRTDD, HANBAISHRYDD, GAIBURENKEISHNCD, HONBUHANBAIKANRISHNCD, MGNTRGTKBN, SHNKBN, MOBILERIYOUMU, TAXSETTEIKBN, TAXKBN, SIIRETRTSKITANI, SIIREIRISU, SIIRETANI, SIIREUNT, HACCHUROTTOKAZU, URITRTSKITANI, URIIRISU, URITANI, OPNPRICEKIRIKAEDD, GENZOPNPRICE, SHINOPNPRICE, GENZOPNMOCHIKAERIPRICE, SHINOPNMOCHIKAERIPRICE, HANSOKUKBN, HANSOKUSTRTDD, HANSOKUSHRYDD, HANSOKUNM, HANSOKUDLVRYPRICE, HANSOKUMOCHIKAERIPRICE, HANSOKUYUSENKBN, ZAIKOKANRITRGTFLG, GENKAKEISANKBN, HYOJUNGENKA, ZAIKOUNT, SIIRETANIHENKANKBN, ZAIKOARAMUSURYO, BIKO, KAIINSAITORENKEIKBN, YUKOKBN, '001', '000', 'SYSTEM', TO_CHAR(SYSDATE, 'YYYYMMDD'), TO_CHAR(SYSTIMESTAMP, 'HH24MISS'), TO_CHAR(SYSDATE, 'YYYYMMDD'), '127.0.0.1', 'MENTE', '001', '000', 'SYSTEM', TO_CHAR(SYSDATE, 'YYYYMMDD'), TO_CHAR(SYSTIMESTAMP, 'HH24MISS'), TO_CHAR(SYSDATE, 'YYYYMMDD'), '127.0.0.1', 'MENTE'
FROM S02M043T S
WHERE S.SHNCD = '099902'
  AND EXISTS (SELECT 1 FROM S02M007T M WHERE M.APKIHONCD = S.APKIHONCD AND M.SHNCD = '099904');

-- 確認後
SELECT '確認後' AS WORKNAME, 'S02M043T' AS TABLENM, Count(*) AS CNT FROM S02M043T WHERE SHNCD IN ('099901', '099902', '099903', '099904');

PAUSE Adjust paper and press RETURN to continue.

commit;

-- END

SELECT 'S02M043T-ED' AS WORKNAME, TO_CHAR(SYSTIMESTAMP, 'YYYY/MM/DD HH24:MI:SS') AS DTM FROM dual;
